//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_CELLULAR_NETWORK_FAILED_REASON(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.CELLULAR_NETWORK_FAILED_REASON
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.CELLULAR_NETWORK_FAILED_REASON_NONE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.CELLULAR_NETWORK_FAILED_REASON
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.CELLULAR_NETWORK_FAILED_REASON_NONE, dec)
	})
}
